class StatusWatchdogError(Exception):
    """ Base status watchdog exception """
    pass


class InvalidBtsType(StatusWatchdogError):
    """ Raised when BTS type is unsupported """
    pass


class BtsConnectionError(StatusWatchdogError):
    """ Raised when connection to BTS cannot be established """
    pass


class WatchdogNotStarted(StatusWatchdogError):
    """ Raised when performing given action was not preceded with starting status watch """


class WatchdogAlreadyStarted(StatusWatchdogError):
    """ Raised when re-starting statuses watch was not preceded with stopping statuses watch """
    pass


class InvalidStatus(StatusWatchdogError):
    """ Raised when status has invalid data """
    pass


class ComponentCheckError(StatusWatchdogError):
    """ Raided when BTS was unavailable during component check or given component doesn't exist on BTS """
    pass


class UnexpectedStatusesDetected(StatusWatchdogError):
    """ Raised when any unexpected status has been detected """
    pass
